function requireRole(role) {
  return (req, res, next) => {
    if (req.user?.role !== role) return res.status(403).json({ error: { code: "FORBIDDEN" } })
    next()
  }
}

app.delete("/api/users/:id", requireRole("admin"), deleteUser)

